          createElement("p", {
            text: "Tip: sudden changes in appetite, energy, grooming, or litter box habits are good reasons to call a veterinarian."
          })
        ]);

        return createElement("div", { className: "page-shell" }, [main, footer]);
      }

      document.getElementById("root").append(App());
    </script>
